const campaign = $('Email Campaigns').first().json;
const lead = $json;

const language = lead.property_language || campaign.property_language || 'English';
const isArabic = language === 'Arabic';

const companyName = lead.name || '';
const contactName = lead.property_contact_name || (isArabic ? 'الأستاذ/الأستاذة' : 'Sir/Madam');

const subject = isArabic
  ? (campaign.property_subject_arabic || campaign.property_subject_line)
  : (campaign.property_subject_english || campaign.property_subject_line);

const rawContent = isArabic
  ? (campaign.property_email_content_arabic || campaign.property_email_content)
  : (campaign.property_email_content_english || campaign.property_email_content);

const ctaText = isArabic
  ? (campaign.property_cta_text_arabic || 'احجز استشارة مجانية')
  : (campaign.property_cta_text_english || 'Book Free Consultation');

const footerText = isArabic
  ? (campaign.property_footer_arabic || '')
  : (campaign.property_footer_english || '');

const ctaUrl = campaign.property_cta_url || 'https://businesspartnerksa.com/book-consultation';

const logoUrl = campaign.property_header_logo_url || '';
const bannerUrl = campaign.property_banner_image_url || '';

const primaryPhone = campaign.property_primary_phone || '+966530540231';
const secondaryPhone = campaign.property_secondary_phone || '+966503793356';
const thirdPhone = campaign.property_third_phone || '+966507034157';
const supportEmail = campaign.property_support_email || 'business@businesspartnerksa.com';

const linkedIn = campaign.property_linked_in_url || 'https://www.linkedin.com/company/businesspartnerksa';
const instagram = campaign.property_instagram_url || 'https://www.instagram.com/businesspartnersa/';
const facebook = campaign.property_facebook_url || 'https://www.facebook.com/BusinessPartnerKsa/';

const personalizedContent = rawContent
  .replaceAll('{company_name}', companyName)
  .replaceAll('{contact_name}', contactName);

const defaultFooter = isArabic
  ? `Business Partner<br>
تأسيس الشركات | الاستثمار الأجنبي | الموارد البشرية | العلاقات الحكومية<br>
الرياض | جدة | المملكة العربية السعودية`
  : `Business Partner<br>
Company Formation | Foreign Investor Setup | HR Operations | Government Relations<br>
Riyadh | Jeddah | Kingdom of Saudi Arabia`;

const htmlBody = `
<div dir="${isArabic ? 'rtl' : 'ltr'}"
style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#1f2937;line-height:1.8;text-align:${isArabic ? 'right' : 'left'};">

  ${logoUrl ? `<div style="text-align:center;margin-bottom:22px;"><img src="${logoUrl}" style="max-width:280px;height:auto;"></div>` : ''}

  ${bannerUrl ? `<img src="${bannerUrl}" style="width:100%;border-radius:12px;margin-bottom:24px;">` : ''}

  <div style="font-size:15px;">
    ${personalizedContent}
  </div>

  <div style="margin:30px 0;text-align:center;">
    <a href="${ctaUrl}" style="background:#08145f;color:#ffffff;padding:14px 26px;border-radius:8px;text-decoration:none;font-weight:bold;display:inline-block;">
      ${ctaText}
    </a>
  </div>

  <hr style="border:none;border-top:1px solid #e5e7eb;margin:28px 0;">

  <div style="font-size:13px;color:#6b7280;">
    ${footerText || defaultFooter}<br><br>
    ${isArabic ? 'الجوال' : 'Phone'}: ${primaryPhone} | ${secondaryPhone} | ${thirdPhone}<br>
    ${isArabic ? 'البريد الإلكتروني' : 'Email'}: <a href="mailto:${supportEmail}">${supportEmail}</a><br><br>
    <a href="${linkedIn}">LinkedIn</a> |
    <a href="${instagram}">Instagram</a> |
    <a href="${facebook}">Facebook</a>
  </div>
</div>
`;

return {
  lead_id: lead.id,
  lead_name: lead.name,
  company_name: companyName,
  contact_name: contactName,
  language,
  subject,
  body: htmlBody
};
